import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    y_at_x = [0] * n
    for i in range(n):
        x, y = data[1 + 2 * i:3 + 2 * i]
        y_at_x[x - 1] = y

    # For a chosen ball, the next state consists of it and all balls
    # incomparable with it that were present in the current state.
    incomparable = [0] * n
    for i in range(n):
        for j in range(n):
            if i == j or (i - j) * (y_at_x[i] - y_at_x[j]) < 0:
                incomparable[i] |= 1 << j

    initial = (1 << n) - 1
    seen = {initial}
    stack = [initial]
    while stack:
        state = stack.pop()
        bits = state
        while bits:
            bit = bits & -bits
            bits -= bit
            i = bit.bit_length() - 1
            nxt = (state & incomparable[i]) | bit
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    print(len(seen) % 998244353)

if __name__ == '__main__':
    solve()

