import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]

    factors = []
    for x in arr:
        d = {}
        q = x
        p = 2
        while p * p <= q:
            while q % p == 0:
                d[p] = d.get(p, 0) + 1
                q //= p
            p += 1
        if q > 1:
            d[q] = d.get(q, 0) + 1
        factors.append(d)

    primes = set().union(*(d.keys() for d in factors)) if factors else set()
    answer = 1
    for prime in primes:
        steps = [d.get(prime, 0) for d in factors]
        bound = sum(steps)
        powers = [pow(prime, h, MOD) for h in range(bound + 1)]

        # z: paths that have not visited height 0; t: paths that have.
        z = [0] * (bound + 1)
        t = [0] * (bound + 1)
        for h in range(bound + 1):
            if h == 0:
                t[h] = powers[h]
            else:
                z[h] = powers[h]

        for step in steps:
            nz = [0] * (bound + 1)
            nt = [0] * (bound + 1)
            for h in range(bound + 1):
                if z[h] == 0 and t[h] == 0:
                    continue
                if step == 0:
                    destinations = (h,)
                else:
                    destinations = (h - step, h + step)
                for nh in destinations:
                    if 0 <= nh <= bound:
                        weight = powers[nh]
                        if nh == 0:
                            nt[nh] = (nt[nh] + (z[h] + t[h]) * weight) % MOD
                        else:
                            nz[nh] = (nz[nh] + z[h] * weight) % MOD
                            nt[nh] = (nt[nh] + t[h] * weight) % MOD
            z, t = nz, nt

        answer = answer * (sum(t) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    solve()

