import sys
MOD=998244353

def main():
 data=list(map(int,sys.stdin.buffer.read().split()))
 if not data:return
 n=data[0]; a=data[1:]
 mx=max(a)
 spf=list(range(mx+1))
 for p in range(2,int(mx**0.5)+1):
  if spf[p]==p:
   for x in range(p*p,mx+1,p):
    if spf[x]==x:spf[x]=p
 phi=list(range(mx+1))
 for p in range(2,mx+1):
  if phi[p]==p:
   for x in range(p,mx+1,p):phi[x]-=phi[x]//p
 sums=[0]*(mx+1)
 cache={}
 ans=0; weight=1
 out=[]
 for x in a:
  ds=cache.get(x)
  if ds is None:
   factors=[]; y=x
   while y>1:
    p=spf[y]; e=0
    while y%p==0:y//=p;e+=1
    factors.append((p,e))
   ds=[1]
   for p,e in factors:
    old=ds[:]; q=1
    for _ in range(e):
     q*=p; ds += [v*q for v in old]
   cache[x]=ds
  c=0
  for d in ds:c+=phi[d]*sums[d]
  c%=MOD
  ans=(2*ans+c)%MOD
  out.append(str(ans))
  for d in ds:sums[d]=(sums[d]+weight)%MOD
  weight=weight*2%MOD
 sys.stdout.write('\n'.join(out))

if __name__=='__main__':main()

