import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = [None]
    for _ in range(m):
        edges.append((next(it) - 1, next(it) - 1, next(it)))

    queries = []
    closed = [False] * (m + 1)
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it)
            queries.append((1, e))
            closed[e] = True
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for e in range(1, m + 1):
        if not closed[e]:
            u, v, w = edges[e]
            dist[u][v] = dist[v][u] = w

    # APSP in the graph after all closures.
    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            row_i = dist[i]
            for j in range(n):
                candidate = dik + row_k[j]
                if candidate < row_i[j]:
                    row_i[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            _, x, y = query
            answers.append(str(dist[x][y] if dist[x][y] < inf else -1))
        else:
            _, e = query
            u, v, w = edges[e]
            # Snapshot distances to both endpoints before inserting the edge.
            to_u = [dist[i][u] for i in range(n)]
            to_v = [dist[i][v] for i in range(n)]
            for i in range(n):
                row = dist[i]
                a, b = to_u[i], to_v[i]
                for j in range(n):
                    candidate = a + w + to_v[j]
                    if candidate < row[j]:
                        row[j] = candidate
                    candidate = b + w + to_u[j]
                    if candidate < row[j]:
                        row[j] = candidate

    print('\n'.join(reversed(answers)))

if __name__ == '__main__':
    main()

