def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]; a=[0]+data[1:]
    pref=[0]*(n+1); seen=set()
    for i in range(1,n+1):
        if a[i] not in seen: seen.add(a[i])
        pref[i]=len(seen)
    nxt=[n+1]*(n+1); last={}
    for i in range(n,0,-1):
        nxt[i]=last.get(a[i],n+1)
        last[a[i]]=i
    suff=[0]*(n+2); seen=set()
    for i in range(n,0,-1):
        seen.add(a[i]); suff[i]=len(seen)
    size=1
    while size<n: size*=2
    neg=-10**9
    mx=[neg]*(2*size); lazy=[0]*(2*size)
    def apply(k,v):
        mx[k]+=v; lazy[k]+=v
    def push(k):
        if lazy[k]:
            v=lazy[k]; apply(k*2,v); apply(k*2+1,v); lazy[k]=0
    def add(ql,qr,v,k=1,l=0,r=None):
        if r is None:r=size
        if ql>r or qr<l:return
        if ql<=l and r<=qr:
            apply(k,v); return
        push(k); m=(l+r)//2
        add(ql,qr,v,k*2,l,m); add(ql,qr,v,k*2+1,m+1,r)
        mx[k]=max(mx[k*2],mx[k*2+1])
    def setpoint(p,v,k=1,l=0,r=None):
        if r is None:r=size
        if l==r:
            mx[k]=v; lazy[k]=0; return
        push(k); m=(l+r)//2
        if p<=m:setpoint(p,v,k*2,l,m)
        else:setpoint(p,v,k*2+1,m+1,r)
        mx[k]=max(mx[k*2],mx[k*2+1])
    def query(ql,qr,k=1,l=0,r=None):
        if r is None:r=size
        if ql<=l and r<=qr:return mx[k]
        push(k);m=(l+r)//2; ans=neg
        if ql<=m:ans=max(ans,query(ql,qr,k*2,l,m))
        if qr>m:ans=max(ans,query(ql,qr,k*2+1,m+1,r))
        return ans
    ans=0
    for l in range(n-1,1,-1):
        lo=l+1; hi=min(n-1,nxt[l]-1)
        if lo<=hi:add(lo,hi,1)
        setpoint(l,1+suff[l+1])
        ans=max(ans,pref[l-1]+query(l,n-1))
    print(ans)
