import sys
from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[:2]
    raw = data[2:]
    processes = [tuple(raw[4*i:4*i+4]) for i in range(n)]

    def min_cost(k, a, p, b, q):
        if k <= 0:
            return 0
        g = gcd(a, b)
        step_s = b // g
        decrease_t = a // g
        best = 10**30

        # Enumerate the number of S machines modulo step_s. Increasing it
        # by step_s permits replacing exactly decrease_t T machines' output.
        for r in range(step_s):
            need = k - r * a
            if need <= 0:
                last = 0
            else:
                initial_t = (need + b - 1) // b
                last = (initial_t + decrease_t - 1) // decrease_t

            candidates = {0, last}
            if last > 0:
                candidates.add(last - 1)
            for t in candidates:
                count_s = r + t * step_s
                remaining = k - count_s * a
                count_t = 0 if remaining <= 0 else (remaining + b - 1) // b
                best = min(best, count_s * p + count_t * q)
        return best

    def feasible(k):
        total = 0
        for a, p, b, q in processes:
            total += min_cost(k, a, p, b, q)
            if total > budget:
                return False
        return True

    low, high = 0, 100 * budget + 1
    while low + 1 < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

if __name__ == '__main__':
    main()

