from math import comb
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        good = [False] * (n + 1)
        for t in range(1, n + 1):
            v = t
            steps = 0
            while v != 1:
                v = v.bit_count()
                steps += 1
            good[t] = steps <= k - 1

        ans = 0
        ones_before = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for t in range(1, n + 1):
                    need = t - ones_before
                    if good[t] and 0 <= need <= rem:
                        ans += comb(rem, need)
                ones_before += 1
        return ans % MOD

