import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    rows = [x.decode() for x in data[1:1 + n]]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for u, row in enumerate(rows):
        for v, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[u][c].append(v)
                incoming[v][c].append(u)

    dist = [[-1] * n for _ in range(n)]
    q = deque()
    for i in range(n):
        dist[i][i] = 0
        q.append((i, i))

    for u in range(n):
        for c in range(26):
            for v in outgoing[u][c]:
                if dist[u][v] == -1:
                    dist[u][v] = 1
                    q.append((u, v))

    while q:
        u, v = q.popleft()
        nd = dist[u][v] + 2
        for c in range(26):
            left = incoming[u][c]
            right = outgoing[v][c]
            if left and right:
                for a in left:
                    row = dist[a]
                    for b in right:
                        if row[b] == -1:
                            row[b] = nd
                            q.append((a, b))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == '__main__':
    main()

