from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        size = n * m
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]  # clockwise order
        rotated = [1, 2, 3, 0]

        # straight[r,c,d,p]: longest straight continuation, where p=0 expects 2, p=1 expects 0
        straight = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]
        turned = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]
        cells = [(r, c, r * m + c) for r in range(n) for c in range(m)]
        orders = [sorted(cells, key=lambda x: -(x[0] * dr + x[1] * dc))
                  for dr, dc in dirs]

        # Calculate paths with no turn.
        for d, (dr, dc) in enumerate(dirs):
            for r, c, idx in orders[d]:
                for phase, value in enumerate((2, 0)):
                    if grid[r][c] != value:
                        continue
                    nr, nc = r + dr, c + dc
                    following = straight[d][1 - phase][nr * m + nc] if 0 <= nr < n and 0 <= nc < m else 0
                    straight[d][phase][idx] = 1 + following

        # Calculate paths where at most one clockwise turn is still available.
        for d, (dr, dc) in enumerate(dirs):
            tr, tc = dirs[rotated[d]]
            for r, c, idx in orders[d]:
                for phase, value in enumerate((2, 0)):
                    if grid[r][c] != value:
                        continue
                    nr, nc = r + dr, c + dc
                    best = 1 + (turned[d][1 - phase][nr * m + nc]
                                if 0 <= nr < n and 0 <= nc < m else 0)
                    nr, nc = r + tr, c + tc
                    if 0 <= nr < n and 0 <= nc < m:
                        best = max(best, 1 + straight[rotated[d]][1 - phase][nr * m + nc])
                    turned[d][phase][idx] = best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        answer = max(answer, 1 + turned[d][0][nr * m + nc])
        return answer

