class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Factorials are capped at k; larger counts are indistinguishable
        # for the purpose of finding the k-th permutation.
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(k, fact[i - 1] * i)

        available = [list(range(1, n + 1, 2)), list(range(2, n + 1, 2))]

        def count_completions(odds: int, evens: int, next_parity: int, slots: int) -> int:
            if slots == 0:
                return int(odds == 0 and evens == 0)
