class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        p10 = [1] * n
        for i in range(1, n):
            p10[i] = p10[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            c = p10[i]
            if i != n - 1 - i:
                c += p10[n - 1 - i]
            coeff.append(c % k)

        allmask = (1 << k) - 1
        dp = [0] * (m + 1)
        dp[m] = 1  # Only remainder 0 is achievable by an empty suffix.
        for i in range(m - 1, -1, -1):
            nxt = dp[i + 1]
            possible = 0
            for d in range(10):
                shift = (d * coeff[i]) % k
                if shift == 0:
                    possible |= nxt
                else:
                    possible |= ((nxt << shift) | (nxt >> (k - shift))) & allmask
            dp[i] = possible

        digits = []
        residue = 0
        for i in range(m):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                new_residue = (residue + d * coeff[i]) % k
                needed = (-new_residue) % k
                if (dp[i + 1] >> needed) & 1:
                    digits.append(str(d))
                    residue = new_residue
                    break

        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

