    # For two functions i and j, placing i outside j is better iff
    # (A_i - 1) / B_i >= (A_j - 1) / B_j.
    # Thus an optimal composition orders them by increasing ratio
    # from inside to outside.
    def compare(x, y):
        lhs=(x[0]-1)*y[1]
        rhs=(y[0]-1)*x[1]
        return (lhs > rhs) - (lhs < rhs)

    fs.sort(key=cmp_to_key(compare))
    dp=[-1]*(k+1)
    dp[0]=1
    for a,b in fs:
        for j in range(k,0,-1):
            if dp[j-1]>=0:
                dp[j]=max(dp[j], a*dp[j-1]+b)
