class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        stars = [i for i, c in enumerate(p) if c == '*']
        A = p[:stars[0]]
        B = p[stars[0] + 1:stars[1]]
        C = p[stars[1] + 1:]
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        ao = occurrences(A)
        bo = occurrences(B)
        co = occurrences(C)
        best = n + 1
        ai = 0
        ci = 0
        for x in bo:
            if A:
                while ai < len(ao) and ao[ai] + len(A) <= x:
                    ai += 1
                if ai == 0:
                    continue
                left = ao[ai - 1]
            else:
                left = x

            y = x + len(B)
            if C:
                while ci < len(co) and co[ci] < y:
                    ci += 1
                if ci == len(co):
                    continue
                right = co[ci] + len(C)
            else:
                right = y
            best = min(best, right - left)

        return -1 if best == n + 1 else best

