    a = data[2:]

    # Enumerate the smaller of a chosen set and its complement.
    r = min(k, n - k)
    total_xor = 0
    for value in a:
        total_xor ^= value

    answer = 0
    use_complement = k > n // 2
    for subset in combinations(a, r):
        value_xor = 0
        for value in subset:
            value_xor ^= value
        if use_complement:
            value_xor ^= total_xor
        if value_xor > answer:
            answer = value_xor

    print(answer)

