import sys

def main():
    data = sys.stdin.buffer.read().split()
    K = int(data[0])
    s, t = data[1], data[2]
    n, m = len(s), len(t)
    if abs(n - m) > K:
        print('No')
        return

    # Wavefront: for each edit count and diagonal, keep the farthest
    # source-string position reachable, then extend through equal characters.
    x = 0
    while x < min(n, m) and s[x] == t[x]:
        x += 1
    if x == n and x == m:
        print('Yes')
        return
    prev = {0: x}
    for d in range(1, K + 1):
        cur = {}
        for diag in range(-d, d + 1):
            best = -1
            # Substitution: same diagonal, advance in both strings.
            v = prev.get(diag)
            if v is not None and v < n and 0 <= v + 1 - diag <= m:
                best = max(best, v + 1)
            # Delete from S: diagonal increases by one.
            v = prev.get(diag - 1)
            if v is not None and v < n and 0 <= v + 1 - diag <= m:
                best = max(best, v + 1)
            # Insert into S: diagonal decreases by one.
            v = prev.get(diag + 1)
            if v is not None and 0 <= v - diag <= m:
                best = max(best, v)
            if best < 0:
                continue
            y = best - diag
            while best < n and y < m and s[best] == t[y]:
                best += 1
                y += 1
            cur[diag] = best
            if best == n and y == m:
                print('Yes')
                return
        prev = cur
    print('No')

if __name__ == '__main__':
    main()

