from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        order = []
        stack = [(0, False)]
        while stack:
            x, done = stack.pop()
            if done:
                order.append(x)
            else:
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))

        pos = [0] * n
        for i, x in enumerate(order):
            pos[x] = i
        size = [1] * n
        for x in order:
            if parent[x] != -1:
                size[parent[x]] += size[x]

        a = ''.join(s[x] for x in order)
        m = len(a)
        odd = [0] * m
        l, r = 0, -1
        for i in range(m):
            k = 1 if i > r else min(odd[l + r - i], r - i + 1)
            while i-k >= 0 and i+k < m and a[i-k] == a[i+k]:
                k += 1
            odd[i] = k
