class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        mins = [None] * k
        mins[0] = 0
        pref = 0
        ans = -10**30

        for i, x in enumerate(nums, 1):
            pref += x
            r = i % k
            if mins[r] is not None:
                ans = max(ans, pref - mins[r])
            if mins[r] is None or pref < mins[r]:
                mins[r] = pref

