class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0
        nxt = [-1] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n - 1
            stack.append(i)
        ans = 0
        i = 0
        while i < n - 1:
            j = nxt[i]
            if j <= i or j >= n:
                j = n - 1
            ans += (j - i) * nums[i]
            i = j
        return ans

