        cnt = Counter(nums)
        total = sum(nums)
        for x in sorted(cnt, reverse=True):
            rem = total - x
            if rem % 2 == 0:
                special_sum = rem // 2
                if cnt[special_sum] - (special_sum == x) > 0:
                    return x
        return 0

