class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        reachable = [1] * n  # Bit s is set iff sum s can be formed.
        done = [value == 0 for value in nums]

        if all(done):
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if done[i]:
                    continue
                reachable[i] |= reachable[i] << value
                reachable[i] &= (1 << (nums[i] + 1)) - 1
                if (reachable[i] >> nums[i]) & 1:
                    done[i] = True

            if all(done):
                return k

        return -1

