class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq
        limit = 10 ** len(str(n))
        prime = [True] * limit
        if limit > 0:
            prime[0] = False
        if limit > 1:
            prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False
        if prime[n] or prime[m]:
            return -1
        dist = [10**30] * limit
        dist[n] = n
        pq = [(n, n)]
        places = [10 ** i for i in range(len(str(n)))]
        while pq:
            cost, x = heapq.heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for place in places:
                digit = (x // place) % 10
                if digit < 9:
                    y = x + place
                    if place == places[-1] and (y // place) % 10 == 0:
                        continue
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(pq, (cost + y, y))
                if digit > 0 and not (place == places[-1] and digit == 1):
                    y = x - place
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(pq, (cost + y, y))
        return -1

