from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the LCP length of nums and nums[i:].
        z = [0] * n
        z[0] = n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        answer = 0

        # Count splits satisfying nums1 is a prefix of nums2.
        for first_len in range(1, n - 1):
            if z[first_len] >= first_len:
                answer += n - first_len - 1

        # For each second-part length, count splits where nums2 is a
        # prefix of nums3, excluding splits already counted above.
        for second_len in range(1, n):
            common = 0
            for first_len in range(n - second_len - 1, 0, -1):
                if nums[first_len] == nums[first_len + second_len]:
                    common += 1
                else:
                    common = 0
                if common >= second_len and z[first_len] < first_len:
                    answer += 1

        return answer

